{
  "verdicts": [
    {
      "candidate_id": "C04",
      "verdict": "true_drift",
      "reason": "The documented top-level `httpx.request` call passes `extensions=...`, but `httpx.request` does not accept an `extensions` parameter.",
      "code_citation": {
        "path": "httpx/_api.py",
        "start_line": 39,
        "end_line": 56,
        "quote": "def request(\n    method: str,\n    url: URL | str,\n    *,\n    params: QueryParamTypes | None = None,\n    content: RequestContent | None = None,\n    data: RequestData | None = None,\n    files: RequestFiles | None = None,\n    json: typing.Any | None = None,\n    headers: HeaderTypes | None = None,\n    cookies: CookieTypes | None = None,\n    auth: AuthTypes | None = None,\n    proxy: ProxyTypes | None = None,\n    timeout: TimeoutTypes = DEFAULT_TIMEOUT_CONFIG,\n    follow_redirects: bool = False,\n    verify: ssl.SSLContext | str | bool = True,\n    trust_env: bool = True,\n) -> Response:"
      },
      "suggested_doc_fix": "Use a Client instance instead, e.g. `client = httpx.Client(); response = client.request(\"CONNECT\", \"https://www.example.com\", extensions=extensions)`."
    }
  ],
  "additional_findings": [
    {
      "finding_id": "AD-1",
      "drift_kind": "signature",
      "explanation": "The documentation calls the top-level `httpx.get` with `extensions=extensions`, but `httpx.get` has no `extensions` parameter.",
      "doc_citation": {
        "path": "docs/advanced/extensions.md",
        "start_line": 168,
        "end_line": 170,
        "quote": "extensions = {\"target\": b\"/test^path\"}\nresponse = httpx.get(\"https://www.example.com\", extensions=extensions)"
      },
      "code_citation": {
        "path": "httpx/_api.py",
        "start_line": 174,
        "end_line": 186,
        "quote": "def get(\n    url: URL | str,\n    *,\n    params: QueryParamTypes | None = None,\n    headers: HeaderTypes | None = None,\n    cookies: CookieTypes | None = None,\n    auth: AuthTypes | None = None,\n    proxy: ProxyTypes | None = None,\n    follow_redirects: bool = False,\n    verify: ssl.SSLContext | str | bool = True,\n    timeout: TimeoutTypes = DEFAULT_TIMEOUT_CONFIG,\n    trust_env: bool = True,\n) -> Response:"
      },
      "proposed_fix": "Change the example to instantiate a client, e.g. `client = httpx.Client(); response = client.get(\"https://www.example.com\", extensions=extensions)`."
    }
  ]
}
